+    await expect(fetchConnectableCloudProviders()).resolves.toEqual([]);
+    mockGet.mockResolvedValueOnce({ data: { providers: 'OURA' } });
+    await expect(fetchConnectableCloudProviders()).resolves.toEqual([]);
